// ── Gemma xray routes ───────────────────────────────────────────────────────

const SHM_XRAY_ROUTES: &str = "/dev/shm/xray-routes.json";

#[derive(Debug, Clone, Deserialize)]
struct XrayRoute {
    tag: String,
    subdomains: Vec<String>,
    backend: GemmaBackend,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "type")]
enum GemmaBackend {
    #[serde(rename = "ingress")]
    Ingress,
    #[serde(rename = "tcp")]
    Tcp { host: String, port: u16 },
    #[serde(rename = "grpc")]
    Grpc {
        host: String,
        port: u16,
        #[serde(rename = "service_name")]
        service_name: String,
    },
    #[serde(rename = "unix")]
    Unix { path: String },
    #[serde(rename = "dns")]
    Dns { host: String, port: u16 },
}

/// Load the Gemma routing map from `/dev/shm/xray-routes.json` if present.
/// Falls back to an empty vector so legacy env-only operation still works.
fn load_xray_routes() -> Vec<XrayRoute> {
    let Ok(raw) = fs::read_to_string(SHM_XRAY_ROUTES) else {
        return vec![];
    };
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&raw) else {
        return vec![];
    };
    value
        .get("xray_routes")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|item| serde_json::from_value(item.clone()).ok())
                .collect()
        })
        .unwrap_or_default()
}

