            format!(
                r#",
      {{ "type": "field", "inboundTag": ["op-tls", "ghostbridge-reality"], "domain": ["full:{domain}"], "outboundTag": "to-{label}" }}"#,
                domain = s.domain,
                label = s.label,
            )
