//! Session management using WireGuard pubkey as identity.
//!
//! Sessions are created when a WireGuard peer connects and
//! destroyed on disconnect or timeout.

use chrono::{DateTime, Utc};
use dashmap::DashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{debug, info, warn};
use uuid::Uuid;

use crate::gcloud_auth::GCloudAuth;
use crate::wireguard::WireGuardIdentity;

const SESSION_TIMEOUT_SECS: i64 = 3600; // 1 hour

/// Represents an active session
#[derive(Debug, Clone)]
pub struct Session {
    pub session_id: String,
    pub pubkey: String,
    pub user_email: Option<String>,
    pub oauth_token: Option<String>,
    pub token_expires_at: Option<DateTime<Utc>>,
    pub created_at: DateTime<Utc>,
    pub last_seen_at: DateTime<Utc>,
}

/// Mapping of WireGuard pubkey to user information
#[derive(Debug, Clone)]
pub struct UserMapping {
    pub pubkey: String,
    pub user_email: String,
    pub allowed_ip: String,
    pub created_at: DateTime<Utc>,
}

/// Manages sessions and their lifecycle
#[derive(Clone)]
pub struct SessionManager {
    sessions: Arc<DashMap<String, Session>>,
    wireguard_users: Arc<DashMap<String, UserMapping>>,
    gcloud_auth: GCloudAuth,
    wireguard: WireGuardIdentity,
    current_session_id: Arc<Mutex<Option<String>>>,
}

impl SessionManager {
    pub fn new() -> anyhow::Result<Self> {
        Self::with_wireguard_interface("wg0")
    }

    pub fn with_wireguard_interface(interface: &str) -> anyhow::Result<Self> {
        // SQL is obsolete in the 3tched architecture.
        // We use in-memory DashMaps to prevent Btrfs mutation loops.
        Ok(Self {
            sessions: Arc::new(DashMap::new()),
            wireguard_users: Arc::new(DashMap::new()),
            gcloud_auth: GCloudAuth::new(),
            wireguard: WireGuardIdentity::with_interface(interface),
            current_session_id: Arc::new(Mutex::new(None)),
        })
    }

    /// Get the GCloud auth provider
    pub fn gcloud_auth(&self) -> &GCloudAuth {
        &self.gcloud_auth
    }

    /// Get the WireGuard identity provider
    pub fn wireguard(&self) -> &WireGuardIdentity {
        &self.wireguard
    }

    /// Create or retrieve session based on WireGuard identity
    pub async fn get_or_create_session_from_wireguard(&self) -> anyhow::Result<Session> {
        let pubkey = self.wireguard.get_local_pubkey()?;
        self.get_or_create_session(&pubkey).await
    }

    /// Get or create a session for a given pubkey
    pub async fn get_or_create_session(&self, pubkey: &str) -> anyhow::Result<Session> {
        let now = Utc::now();

        // Check for existing valid session
        if let Some(mut session_ref) = self.sessions.iter_mut().find(|r| {
            r.pubkey == pubkey && (now - r.last_seen_at).num_seconds() < SESSION_TIMEOUT_SECS
        }) {
            debug!("Found existing session: {}", session_ref.session_id);
            session_ref.last_seen_at = now;
            let session = session_ref.clone();

            *self.current_session_id.lock().await = Some(session.session_id.clone());
            return Ok(session);
        }

        // Create new session
        let session_id = Uuid::new_v4().to_string();
        info!(
            "Creating new session: {} for pubkey: {}",
            session_id, pubkey
        );

        // Try to get user email from WireGuard user mapping
        let user_email = self
            .wireguard_users
            .get(pubkey)
            .map(|u| u.user_email.clone());

        // Try to get OAuth token
        let (oauth_token, token_expires_at) = match self.gcloud_auth.get_token().await {
            Ok((token, expires)) => (Some(token), Some(expires)),
            Err(e) => {
                warn!("Could not get OAuth token: {}", e);
                (None, None)
            }
        };

        let session = Session {
            session_id: session_id.clone(),
            pubkey: pubkey.to_string(),
            user_email,
            oauth_token,
            token_expires_at,
            created_at: now,
            last_seen_at: now,
        };

        self.sessions.insert(session_id.clone(), session.clone());

        // Store current session ID
        *self.current_session_id.lock().await = Some(session_id);

        Ok(session)
    }

    /// Get the current session ID
    pub async fn current_session_id(&self) -> Option<String> {
        self.current_session_id.lock().await.as_ref().cloned()
    }

    /// Update last_seen timestamp for current session
    pub async fn touch_session(&self) -> anyhow::Result<()> {
        let session_id = self.current_session_id.lock().await.as_ref().cloned();

        if let Some(id) = session_id {
            if let Some(mut session) = self.sessions.get_mut(&id) {
                session.last_seen_at = Utc::now();
            }
        }

        Ok(())
    }

    /// Get a valid OAuth token, refreshing if necessary
    pub async fn get_valid_token(&self) -> anyhow::Result<String> {
        let session_id = self.current_session_id.lock().await.as_ref().cloned();

        if let Some(id) = session_id {
            if let Some(session) = self.sessions.get(&id) {
                if let (Some(token), Some(expires_at)) =
                    (&session.oauth_token, session.token_expires_at)
                {
                    // Token valid for at least 5 more minutes
                    if expires_at > Utc::now() + chrono::Duration::minutes(5) {
                        return Ok(token.clone());
                    }
                }
            }
        }

        // Refresh token
        let (token, expires_at) = self.gcloud_auth.get_token().await?;

        // Update in session
        if let Some(id) = self.current_session_id.lock().await.as_ref().cloned() {
            if let Some(mut session) = self.sessions.get_mut(&id) {
                session.oauth_token = Some(token.clone());
                session.token_expires_at = Some(expires_at);
            }
        }

        Ok(token)
    }

    /// Register a WireGuard user mapping
    pub async fn register_wireguard_user(
        &self,
        pubkey: &str,
        user_email: &str,
        allowed_ip: &str,
    ) -> anyhow::Result<()> {
        let mapping = UserMapping {
            pubkey: pubkey.to_string(),
            user_email: user_email.to_string(),
            allowed_ip: allowed_ip.to_string(),
            created_at: Utc::now(),
        };

        self.wireguard_users.insert(pubkey.to_string(), mapping);

        info!("Registered WireGuard user: {} -> {}", pubkey, user_email);
        Ok(())
    }

    /// Get user email for a pubkey
    pub async fn get_user_for_pubkey(&self, pubkey: &str) -> anyhow::Result<Option<String>> {
        Ok(self
            .wireguard_users
            .get(pubkey)
            .map(|u| u.user_email.clone()))
    }

    /// Clean up expired sessions
    pub async fn cleanup_expired_sessions(&self) -> anyhow::Result<usize> {
        let now = Utc::now();
        let mut deleted = 0;

        self.sessions.retain(|_, session| {
            if (now - session.last_seen_at).num_seconds() >= SESSION_TIMEOUT_SECS {
                deleted += 1;
                false
            } else {
                true
            }
        });

        if deleted > 0 {
            info!("Cleaned up {} expired sessions", deleted);
        }

        Ok(deleted)
    }

    /// Invalidate a specific session
    pub async fn invalidate_session(&self, session_id: &str) -> anyhow::Result<()> {
        self.sessions.remove(session_id);

        // Clear current session if it matches
        let mut current_guard = self.current_session_id.lock().await;
        if current_guard.as_deref() == Some(session_id) {
            *current_guard = None;
        }

        info!("Invalidated session: {}", session_id);
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_session_creation() {
        let manager = SessionManager::new().unwrap();
        let session = manager.get_or_create_session("test-pubkey").await.unwrap();
        assert_eq!(session.pubkey, "test-pubkey");
        assert!(manager.current_session_id().await.is_some());
    }

    #[tokio::test]
    async fn test_session_touch() {
        let manager = SessionManager::new().unwrap();
        let session = manager.get_or_create_session("test-pubkey").await.unwrap();
        let last_seen = session.last_seen_at;

        tokio::time::sleep(tokio::time::Duration::from_millis(10)).await;
        manager.touch_session().await.unwrap();

        let updated = manager.get_or_create_session("test-pubkey").await.unwrap();
        assert!(updated.last_seen_at > last_seen);
    }

    #[tokio::test]
    async fn test_wireguard_user_registration() {
        let manager = SessionManager::new().unwrap();
        manager
            .register_wireguard_user("pubkey1", "user@example.com", "10.0.0.1")
            .await
            .unwrap();

        let email = manager.get_user_for_pubkey("pubkey1").await.unwrap();
        assert_eq!(email, Some("user@example.com".to_string()));
    }
}

//! Seed-derived WireGuard identity + local, non-custodial recovery.
//!
//! The user *is* their WireGuard key. To make identity recoverable without any
//! server-side custody, the keypair is derived deterministically from a 256-bit
//! recovery seed (rendered as a BIP39 mnemonic the user backs up OFF the machine).
//! Re-deriving from the same seed yields the same pubkey, which the server
//! recognizes via `user_exists` — no PII, no custodian.
//!
//! Custody is LOCAL-ONLY: the seed is written under the user's config dir with
//! `0600` (owner-only) permissions. The server never sees the seed or private key.
//! If the machine is lost and no off-machine mnemonic backup exists, the identity
//! is unrecoverable by design — there is no server lever to pull.

use anyhow::{anyhow, Context, Result};
use bip39::Mnemonic;
use rand::rngs::OsRng;
use rand::RngCore;

use crate::registration::WireGuardKeyPair;

/// Domain-separation context for the Blake3 KDF.
const KDF_CONTEXT: &str = "op-identity wireguard-identity v1";

/// Generate a fresh 256-bit recovery seed.
pub fn generate_seed() -> [u8; 32] {
    let mut seed = [0u8; 32];
    OsRng.fill_bytes(&mut seed);
    seed
}

/// Render a 256-bit seed as a 24-word BIP39 mnemonic (the recovery phrase).
pub fn seed_to_mnemonic(seed: &[u8; 32]) -> Result<String> {
    let m = Mnemonic::from_entropy(seed).context("seed -> mnemonic")?;
    Ok(m.to_string())
}

/// Parse a BIP39 mnemonic back into its 256-bit seed (recovery).
pub fn mnemonic_to_seed(mnemonic: &str) -> Result<[u8; 32]> {
    let m =
        Mnemonic::parse(mnemonic.trim()).map_err(|e| anyhow!("invalid recovery phrase: {e}"))?;
    let (entropy, len) = m.to_entropy_array();
    if len != 32 {
        return Err(anyhow!(
            "recovery phrase must encode 256 bits (24 words), got {len} bytes"
        ));
    }
    let mut out = [0u8; 32];
    out.copy_from_slice(&entropy[..32]);
    Ok(out)
}

/// Deterministically derive the WireGuard keypair from a recovery seed.
/// The same seed always yields the same pubkey (= the stable identity).
pub fn derive_keypair(seed: &[u8; 32]) -> WireGuardKeyPair {
    use base64::{engine::general_purpose::STANDARD as BASE64, Engine};
    use x25519_dalek::{PublicKey, StaticSecret};

    let key_material = blake3::derive_key(KDF_CONTEXT, seed);
    let secret = StaticSecret::from(key_material);
    let public = PublicKey::from(&secret);
    WireGuardKeyPair {
        private_key: *************(secret.as_bytes()),
        public_key: *************(public.as_bytes()),
    }
}

/// Recover the keypair from a backed-up mnemonic.
pub fn recover_keypair(mnemonic: &str) -> Result<WireGuardKeyPair> {
    Ok(derive_keypair(&mnemonic_to_seed(mnemonic)?))
}

/// Local-only seed store path: `<config_dir>/op-identity/seed.mnemonic`.
fn seed_path() -> Result<std::path::PathBuf> {
    let dir = dirs::config_dir()
        .ok_or_else(|| anyhow!("no user config dir"))?
        .join("op-identity");
    std::fs::create_dir_all(&dir).context("create op-identity config dir")?;
    Ok(dir.join("seed.mnemonic"))
}

/// Write the mnemonic to the local store with owner-only (0600) permissions.
/// The server never holds this; only the local user can read it.
pub fn store_mnemonic_local(mnemonic: &str) -> Result<std::path::PathBuf> {
    use std::io::Write;
    use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};

    let path = seed_path()?;
    let mut f = std::fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .mode(0o600)
        .open(&path)
        .with_context(|| format!("open {}", path.display()))?;
    f.write_all(mnemonic.trim().as_bytes())?;
    f.write_all(b"\n")?;
    // Re-assert perms in case the file pre-existed with looser bits.
    std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600))?;
    Ok(path)
}

/// Load the locally stored mnemonic, if present.
pub fn load_mnemonic_local() -> Result<String> {
    let path = seed_path()?;
    let s = std::fs::read_to_string(&path).with_context(|| format!("read {}", path.display()))?;
    Ok(s.trim().to_string())
}

/// First-run provisioning: mint a seed, store it locally (0600), derive the keypair.
/// Returns the keypair plus the mnemonic to surface to the user ONCE for off-machine backup.
pub fn provision_local_identity() -> Result<(WireGuardKeyPair, String)> {
    let seed = generate_seed();
    let mnemonic = seed_to_mnemonic(&seed)?;
    store_mnemonic_local(&mnemonic)?;
    let keypair = derive_keypair(&seed);
    Ok((keypair, mnemonic))
}

