//! Local, non-custodial identity vault.
//!
//! Maps a WireGuard pubkey (the user's machine identity) to a sparse user
//! record. The vault is stored in `/etc/ghostbridge/user-vault.json` with
//! 0600 permissions. It is the only server-side record we keep: no private
//! keys, no recovery seeds, no OAuth refresh tokens — just the pubkey and
//! enough metadata to recognize a re-derived identity.
//!
//! Per AGENTS.md: no SQLite, no Btrfs mutation loops, D-Bus-first control plane.
//! This file is read/written by the `session` module only; external tools go
//! through the SessionManager D-Bus projection.

use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io::Write;
use std::os::unix::fs::OpenOptionsExt;
use std::path::Path;
use tracing::info;

const VAULT_PATH: &str = "/etc/ghostbridge/user-vault.json";

/// Sparse user record stored in the vault.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UserRecord {
    pub pubkey: String,
    pub user_email: String,
    pub allowed_ip: String,
    pub created_at: DateTime<Utc>,
    pub provisioned_at: DateTime<Utc>,
}

/// On-disk layout for the vault file.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct VaultFile {
    version: u32,
    users: HashMap<String, UserRecord>,
}

/// Identity vault: pubkey → user record.
#[derive(Debug, Clone, Default)]
pub struct IdentityVault {
    users: HashMap<String, UserRecord>,
}

impl IdentityVault {
    /// Load the vault from disk, or start empty if it does not exist.
    pub fn load() -> Result<Self> {
        if !Path::new(VAULT_PATH).exists() {
            return Ok(Self::default());
        }
        let raw = fs::read_to_string(VAULT_PATH)
            .with_context(|| format!("failed to read identity vault: {VAULT_PATH}"))?;
        let file: VaultFile = serde_json::from_str(&raw)
            .with_context(|| "failed to parse identity vault as JSON")?;
        Ok(Self { users: file.users })
    }

    /// Store a user record, overwriting any existing record for the pubkey.
    pub fn store(&mut self, record: UserRecord) -> Result<()> {
        self.users.insert(record.pubkey.clone(), record);
        self.flush()
    }

    /// Get a user record by pubkey.
    pub fn get(&self, pubkey: &str) -> Option<&UserRecord> {
        self.users.get(pubkey)
    }

    /// Remove a user record.
    pub fn remove(&mut self, pubkey: &str) -> Result<()> {
        self.users.remove(pubkey);
        self.flush()
    }

    /// Persist the vault to disk atomically with owner-only permissions.
    fn flush(&self) -> Result<()> {
        let file = VaultFile {
            version: 1,
            users: self.users.clone(),
        };
        let json = serde_json::to_string_pretty(&file)
            .context("serialize identity vault")?;

        let tmp = format!("{}.tmp", VAULT_PATH);
        let mut f = fs::OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .mode(0o600)
            .open(&tmp)
            .with_context(|| format!("open temp vault file: {tmp}"))?;
        f.write_all(json.as_bytes())
            .with_context(|| format!("write temp vault file: {tmp}"))?;
        f.sync_data()
            .with_context(|| format!("sync temp vault file: {tmp}"))?;
        drop(f);
        fs::rename(&tmp, VAULT_PATH)
            .with_context(|| format!("rename temp vault to: {VAULT_PATH}"))?;
        info!("Persisted identity vault with {} records", self.users.len());
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn round_trip_user_record() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("vault.json");
        // Override the constant path by writing to a temp file manually.
        let record = UserRecord {
            pubkey: "pubkey1".to_string(),
            user_email: "user@example.com".to_string(),
            allowed_ip: "10.0.0.1".to_string(),
            created_at: Utc::now(),
            provisioned_at: Utc::now(),
        };
        let file = VaultFile {
            version: 1,
            users: HashMap::from([("pubkey1".to_string(), record.clone())]),
        };
        fs::write(&path, serde_json::to_string_pretty(&file).unwrap()).unwrap();

        let raw = fs::read_to_string(&path).unwrap();
        let parsed: VaultFile = serde_json::from_str(&raw).unwrap();
        assert_eq!(parsed.users["pubkey1"].user_email, "user@example.com");
    }
}

