pub const DEFAULT_VAULT_PATH: &str = "/etc/ghostbridge/user-vault.json";

/// Sparse user record stored in the vault.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UserRecord {
    pub pubkey: String,
