/* ── Chat send handler — wired to the zeroclaw assistant endpoint ── */
const handleSend = async () => {
  if (!draft.trim() || !connected) return;
  const userMsg: ChatMessage = {
    id: `msg-${Date.now()}`,
    role: "user",
    content: draft.trim(),
    timestamp: Date.now(),
  };
  setMessages((prev) => [...prev, userMsg]);
  setDraft("");
  setSending(true);

  try {
    const response = await fetch("/api/assistant/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        message: userMsg.content,
        session_id: activeSled?.traceId,
      }),
    });

    const data = await response.text();
    let content = data;
    try {
      const parsed = JSON.parse(data);
      content =
        typeof parsed.content === "string"
          ? parsed.content
          : typeof parsed.response === "string"
            ? parsed.response
            : typeof parsed.message === "string"
              ? parsed.message
              : data;
    } catch {
      // Not JSON — display the raw response text.
    }

    const assistantMsg: ChatMessage = {
      id: `msg-${Date.now()}-resp`,
      role: "assistant",
      content,
      timestamp: Date.now(),
    };
    setMessages((prev) => [...prev, assistantMsg]);
    setActiveSled((prev) =>
      prev ? { ...prev, mutationIndex: prev.mutationIndex + 1 } : prev,
    );
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : "Chat request failed";
    setMessages((prev) => [
      ...prev,
      {
        id: `msg-${Date.now()}-err`,
        role: "assistant",
        content: `Error: ${errorMsg}`,
        timestamp: Date.now(),
      },
    ]);
  } finally {
    setSending(false);
  }
};

